import type { Shadow, Theme } from "../source/theme.ts";

const header =
  "/* Generated by @ome-labs/tokens from tokens/*.json: edit the JSON, then run `pnpm build`. */";

export function shadowCss(layers: Shadow[]): string {
  return layers
    .map(
      ({ color, offsetX, offsetY, blur, spread }) =>
        `${offsetX.value}px ${offsetY.value}px ${blur.value}px ${spread.value}px ${color}`,
    )
    .join(", ");
}

const em = (value: number) => `${Number(value.toFixed(4))}em`;

/**
 * The web theme for Tailwind 4: semantic colours as `--ome-*` custom properties per theme, mapped
 * into `@theme inline` so utilities follow the theme, plus fonts, text styles, spacing, radii,
 * shadows, easings and breakpoints. Tailwind's default palette, fonts and sizes are cleared so only
 * kit values exist.
 */
export function webCss(theme: Theme): string {
  const variables = (mode: "light" | "dark") =>
    theme.semantic.map((color) => `  ${color.variable}: ${color[mode]};`).join("\n");

  const text = theme.text.flatMap((style) => [
    `  --text-${style.name}: ${style.size}px;`,
    `  --text-${style.name}--line-height: ${style.lineHeight};`,
    `  --text-${style.name}--letter-spacing: ${em(style.letterSpacing)};`,
    `  --text-${style.name}--font-weight: ${style.weight};`,
  ]);

  const typeUtilities = theme.text.map((style) =>
    [
      `@utility type-${style.name} {`,
      `  font-family: var(--font-${style.family});`,
      `  font-size: var(--text-${style.name});`,
      `  line-height: var(--text-${style.name}--line-height);`,
      `  letter-spacing: var(--text-${style.name}--letter-spacing);`,
      `  font-weight: var(--text-${style.name}--font-weight);`,
      ...(style.uppercase ? ["  text-transform: uppercase;"] : []),
      "}",
    ].join("\n"),
  );

  const breakpoints = theme.layout.breakpoint as Record<string, number>;

  return [
    header,
    "",
    // `dark:` follows the data-theme attribute the theme provider sets (it resolves "system" itself).
    '@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));',
    "",
    ":root {",
    "  color-scheme: light;",
    variables("light"),
    "}",
    "",
    '[data-theme="dark"] {',
    "  color-scheme: dark;",
    variables("dark"),
    "}",
    "",
    // Without an explicit choice the page follows the system until the provider sets data-theme.
    "@media (prefers-color-scheme: dark) {",
    '  :root:not([data-theme="light"]) {',
    "    color-scheme: dark;",
    theme.semantic.map((color) => `    ${color.variable}: ${color.dark};`).join("\n"),
    "  }",
    "}",
    "",
    "@theme inline {",
    "  --color-*: initial;",
    "  --color-transparent: transparent;",
    "  --color-current: currentColor;",
    theme.semantic.map((color) => `  --color-${color.utility}: var(${color.variable});`).join("\n"),
    "}",
    "",
    "@theme {",
    "  --font-*: initial;",
    ...Object.entries(theme.families).map(
      ([name, stack]) =>
        `  --font-${name}: ${stack.map((font) => (font.includes(" ") ? `"${font}"` : font)).join(", ")};`,
    ),
    "  --text-*: initial;",
    ...text,
    "  --spacing: 0.25rem;",
    "  --radius-*: initial;",
    ...theme.radius.map((radius) => `  --radius-${radius.name}: ${radius.px}px;`),
    "  --shadow-*: initial;",
    ...theme.elevation.map(
      (elevation) => `  --shadow-${elevation.name}: ${shadowCss(elevation.layers)};`,
    ),
    ...theme.control.map((control) => `  --height-control-${control.name}: ${control.px}px;`),
    "  --ease-*: initial;",
    ...theme.easing.map(
      (easing) => `  --ease-${easing.name}: cubic-bezier(${easing.curve.join(", ")});`,
    ),
    // Tailwind's `duration-*` utility reads this namespace, so `duration-fast` is the kit's 120 ms.
    ...theme.duration.map(
      (duration) => `  --transition-duration-${duration.name}: ${duration.ms}ms;`,
    ),
    "  --breakpoint-*: initial;",
    ...Object.entries(breakpoints)
      .filter(([name]) => name !== "mobile")
      .map(([name, px]) => `  --breakpoint-${name}: ${px}px;`),
    "}",
    "",
    ...typeUtilities,
    "",
    "@utility h-control-* {",
    "  height: --value(--height-control-*);",
    "}",
    "",
    // Kit rule (page 18): nothing animates for people who ask for reduced motion.
    "@media (prefers-reduced-motion: reduce) {",
    "  *, *::before, *::after {",
    "    animation-duration: 0.01ms !important;",
    "    animation-iteration-count: 1 !important;",
    "    transition-duration: 0.01ms !important;",
    "  }",
    "}",
    "",
  ].join("\n");
}
